### Objective
Build a production-grade Offline Bookmarks & Reading List application in Flutter using `package:hive` and `package:hive_flutter`. Demonstrate custom model definition with `@HiveType`, manual `TypeAdapter` implementation, encrypted box creation using `FlutterSecureStorage`, real-time UI reactivity via `box.listenable()`, and box compaction.

```dart
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:hive_flutter/hive_flutter.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 1. Initialize Hive with the platform directory
  await Hive.initFlutter();

  // 2. Register custom TypeAdapters before opening any boxes
  Hive.registerAdapter(BookmarkAdapter());

  // 3. Obtain encryption key securely from Keychain/Keystore
  const secureStorage = FlutterSecureStorage();
  var encodedKey = await secureStorage.read(key: 'hive_encryption_key');
  if (encodedKey == null) {
    final key = Hive.generateSecureKey();
    encodedKey = base64UrlEncode(key);
    await secureStorage.write(key: 'hive_encryption_key', value: encodedKey);
  }
  final encryptionKey = base64Url.decode(encodedKey);

  // 4. Open our strongly typed, encrypted box
  final bookmarkBox = await Hive.openBox<Bookmark>(
    'bookmarks_vault',
    encryptionCipher: HiveAesCipher(encryptionKey),
  );

  runApp(HiveBookmarksApp(bookmarkBox: bookmarkBox));
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODEL & MANUAL TYPE ADAPTER
// ─────────────────────────────────────────────────────────────────────────────

class Bookmark {
  final String id;
  final String title;
  final String author;
  final DateTime createdAt;
  final bool isRead;

  Bookmark({
    required this.id,
    required this.title,
    required this.author,
    required this.createdAt,
    this.isRead = false,
  });

  Bookmark copyWith({bool? isRead}) {
    return Bookmark(
      id: id,
      title: title,
      author: author,
      createdAt: createdAt,
      isRead: isRead ?? this.isRead,
    );
  }
}

/// Custom TypeAdapter serialization logic (typeId: 1)
class BookmarkAdapter extends TypeAdapter<Bookmark> {
  @override
  final int typeId = 1;

  @override
  Bookmark read(BinaryReader reader) {
    final numOfFields = reader.readByte();
    final fields = <int, dynamic>{
      for (int i = 0; i < numOfFields; i++) reader.readByte(): reader.read(),
    };

    return Bookmark(
      id: fields[0] as String,
      title: fields[1] as String,
      author: fields[2] as String,
      createdAt: DateTime.fromMillisecondsSinceEpoch(fields[3] as int),
      isRead: fields[4] as bool? ?? false,
    );
  }

  @override
  void write(BinaryWriter writer, Bookmark obj) {
    writer
      ..writeByte(5) // Number of fields
      ..writeByte(0)
      ..write(obj.id)
      ..writeByte(1)
      ..write(obj.title)
      ..writeByte(2)
      ..write(obj.author)
      ..writeByte(3)
      ..write(obj.createdAt.millisecondsSinceEpoch)
      ..writeByte(4)
      ..write(obj.isRead);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class HiveBookmarksApp extends StatelessWidget {
  final Box<Bookmark> bookmarkBox;
  const HiveBookmarksApp({super.key, required this.bookmarkBox});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Hive Persistence Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.amber.shade800,
        useMaterial3: true,
      ),
      home: BookmarksHomeScreen(box: bookmarkBox),
    );
  }
}

class BookmarksHomeScreen extends StatelessWidget {
  final Box<Bookmark> box;
  const BookmarksHomeScreen({super.key, required this.box});

  void _addSampleBookmark() {
    final id = DateTime.now().millisecondsSinceEpoch.toString();
    final newBookmark = Bookmark(
      id: id,
      title: 'Mastering Flutter Architecture #$id',
      author: 'Flutter Engineering Guild',
      createdAt: DateTime.now(),
    );
    box.put(id, newBookmark);
  }

  void _toggleReadStatus(Bookmark bookmark) {
    final updated = bookmark.copyWith(isRead: !bookmark.isRead);
    box.put(bookmark.id, updated);
  }

  void _deleteBookmark(String id) {
    box.delete(id);
  }

  Future<void> _compactDatabase(BuildContext context) async {
    await box.compact();
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Hive binary box compacted & defragmented!'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Hive Encrypted Bookmarks'),
        centerTitle: true,
        actions: [
          IconButton(
            icon: const Icon(Icons.cleaning_services_rounded),
            tooltip: 'Compact Box Storage',
            onPressed: () => _compactDatabase(context),
          ),
        ],
      ),
      body: ValueListenableBuilder<Box<Bookmark>>(
        valueListenable: box.listenable(),
        builder: (context, currentBox, _) {
          if (currentBox.isEmpty) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.inventory_2_outlined, size: 64, color: Colors.amber.shade800),
                    const SizedBox(height: 16),
                    const Text(
                      'No Bookmarks Cached in Hive',
                      style: TextStyle(fontWeight: FontWeight.bold, fontSize: 18),
                    ),
                    const SizedBox(height: 8),
                    const Text(
                      'Tap the FAB below to add a strongly typed Bookmark entity to the AES-256 encrypted Hive box.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: Colors.black54, fontSize: 13),
                    ),
                  ],
                ),
              ),
            );
          }

          final bookmarks = currentBox.values.toList();

          return ListView.separated(
            padding: const EdgeInsets.all(16),
            itemCount: bookmarks.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) {
              final bookmark = bookmarks[index];

              return Card(
                elevation: 1,
                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                child: ListTile(
                  contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  leading: CircleAvatar(
                    backgroundColor: bookmark.isRead ? Colors.green.shade50 : Colors.amber.shade50,
                    child: Icon(
                      bookmark.isRead ? Icons.bookmark_added_rounded : Icons.bookmark_border_rounded,
                      color: bookmark.isRead ? Colors.green : Colors.amber.shade900,
                    ),
                  ),
                  title: Text(
                    bookmark.title,
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      decoration: bookmark.isRead ? TextDecoration.lineThrough : null,
                    ),
                  ),
                  subtitle: Text(
                    '${bookmark.author} • ${bookmark.createdAt.toLocal().toString().split('.')[0]}',
                    style: const TextStyle(fontSize: 11, color: Colors.black54),
                  ),
                  trailing: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      IconButton(
                        icon: Icon(
                          bookmark.isRead ? Icons.undo_rounded : Icons.check_circle_outline,
                          color: Colors.teal,
                        ),
                        onPressed: () => _toggleReadStatus(bookmark),
                      ),
                      IconButton(
                        icon: const Icon(Icons.delete_outline, color: Colors.redAccent),
                        onPressed: () => _deleteBookmark(bookmark.id),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _addSampleBookmark,
        icon: const Icon(Icons.bookmark_add_rounded),
        label: const Text('Add Bookmark'),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Pure Dart Binary Adapter**:
   `BookmarkAdapter` implements `TypeAdapter<Bookmark>`. It serializes field indices directly to binary bytes via `reader` and `writer`, completely bypassing JSON text decoding overhead.
2. **Encrypted Box Initialization**:
   `Hive.openBox<Bookmark>('bookmarks_vault', encryptionCipher: HiveAesCipher(key))` applies AES-256 encryption across all disk blocks. The key is secured in `FlutterSecureStorage`.
3. **Reactive UI Binding with box.listenable()**:
   `ValueListenableBuilder<Box<Bookmark>>(valueListenable: box.listenable())` listens to all box mutations. When `box.put()` or `box.delete()` executes, the UI rebuilds immediately with zero manual state orchestration.
